def compare(s):
    comparison = compare_offers(s["offers"], s["plan"])
    return {"comparison": comparison, **event("compare_offers", f"{len(comparison['eligible'])} eligible, {len(comparison['excluded'])} excluded, {len(comparison['uncertain'])} uncertain", "code")}

